        preview.onEditCardCode { $0 }
        preview.onEditNotes { $0 }
        preview.onEditIdentity { $0 }
        preview.onEditFavorite { $0 }
        preview.onEditReprompt { $0 }
        configure(preview)
        do {
            return try connect(OahuConnection(previewPort: port))
        } catch {
            preconditionFailure("The CipherAddEdit preview could not connect: \(error)")
        }
    }
}

// MARK: - Screen provider

@objc(OAHUScreen_cc53762528b0fd42ba406df0609589f7e3fb2ab0ff03fb1c1815171e4c71d2c7)
public final class CipherAddEditScreenProvider: NSObject, ScreenProvider {
    private static let log = Logger(subsystem: "OahuRuntime", category: "screens")

    public func contractHash(_ contract: String) -> Int64 {
        contract == CipherAddEditContract.name ? CipherAddEditContract.hash : 0
    }

    public func createScreen(_ contract: String, hash: Int64, port: OahuPort) -> ScreenHandle? {
        guard contract == CipherAddEditContract.name else { return nil }
        guard hash == CipherAddEditContract.hash, port.contractHash == hash, port.contractName == contract else {
            Self.log.error("Refusing \(contract, privacy: .public): the port's hash is \(port.contractHash), this library was built against \(CipherAddEditContract.hash)")
            return nil
        }
        let model: CipherAddEditModel
        do {
            model = try CipherAddEditModel.connect(port)
        } catch {
            Self.log.error("CipherAddEdit could not connect: \(error, privacy: .public)")
            return nil
        }
        return OahuScreen(rootView: CipherAddEditScreen(model: model)) { model.close() }
    }
}
